        return None

    if sysdefs is None:
        sysdefs = {}

    if name.lower().startswith('lo') or name.lower().startswith('po'):
        return True

    if mode == 'layer2':
        return sysdefs.get('L2_enabled', False)

    if mode == 'layer3':
        return sysdefs.get('L3_enabled', False)

