export function pillRoomNotifPos(text: string): number {
    return text.indexOf("@room");
}

export function pillRoomNotifLen(): number {
    return "@room".length;
}

export function Pill({
    type,
    url,
    inMessage = false,
    room,
    shouldShowPillAvatar = false,
}: IProps): JSX.Element | null {
    const { avatar, text, onClick, resourceId, type: resolvedType } = usePermalink({ room, type, url });
    const [hover, setHover] = useState(false);

    const matrixClient = MatrixClientPeg.get();

    let pillClass: string | undefined;
    let userId: string | undefined;
    let href: string | null = url;

    if (resolvedType === PillType.AtRoomMention) {
        pillClass = "mx_AtRoomPill";
    } else if (resolvedType === PillType.UserMention) {
        pillClass = "mx_UserPill";
        userId = resourceId;
        if (inMessage) {
            href = null;
        }
    } else if (resolvedType === PillType.RoomMention || resolvedType === "space") {
        pillClass = resolvedType === "space" ? "mx_SpacePill" : "mx_RoomPill";
    }

    if (!resolvedType || !text) {
        return null;
    }

    const classes = classNames("mx_Pill", pillClass, {
        mx_UserPill_me: userId === matrixClient.getUserId(),
    });

    const tip = hover && resourceId ? <Tooltip label={resourceId} alignment={Alignment.Right} /> : null;

    const content = (
        <>
            {avatar}
            <span className="mx_Pill_linkText">{text}</span>
            {tip}
        </>
    );

    return (
        <bdi>
            <MatrixClientContext.Provider value={matrixClient}>
                {inMessage ? (
                    <a
                        className={classes}
                        href={href}
                        onClick={onClick}
                        onMouseOver={() => setHover(true)}
                        onMouseLeave={() => setHover(false)}
                    >
                        {content}
                    </a>
                ) : (
                    <span
                        className={classes}
                        onMouseOver={() => setHover(true)}
