export function Pill({ type, url, inMessage, room, shouldShowPillAvatar }: IProps): JSX.Element | null {
    const [hover, setHover] = useState(false);
    const { avatar, text, onClick, resourceId, type: resolvedType } = usePermalink({ room, type, url });

    // If the type cannot be resolved, render nothing (fail quiet)
    if (!resolvedType) {
        return null;
    }

    const matrixClient = MatrixClientPeg.get();
    const isMe = resolvedType === PillType.UserMention && resourceId === matrixClient.getUserId();

    let pillClass: string | undefined;
    if (resolvedType === PillType.AtRoomMention) {
        pillClass = "mx_AtRoomPill";
    } else if (resolvedType === PillType.UserMention) {
        pillClass = "mx_UserPill";
    } else if (resolvedType === PillType.RoomMention || resolvedType === "space") {
        pillClass = "mx_RoomPill";
    }

    const classes = classNames("mx_Pill", pillClass, {
        mx_UserPill_me: isMe,
    });

    let tip;
    if (hover && resourceId) {
        tip = <Tooltip label={resourceId} alignment={Alignment.Right} />;
    }

    const avatarEl = shouldShowPillAvatar ? avatar : null;

    const content = (
        <>
            {avatarEl}
            <span className="mx_Pill_linkText">{text}</span>
            {tip}
        </>
    );

