+import React, { useEffect, useRef, useState } from "react";
+import { Room } from "matrix-js-sdk/src/models/room";
+import { RoomMember } from "matrix-js-sdk/src/models/room-member";
+import { MatrixClient } from "matrix-js-sdk/src/client";
+import { logger } from "matrix-js-sdk/src/logger";
+import { getPrimaryPermalinkEntity, parsePermalink } from "../utils/permalinks/Permalinks";
+import { MatrixClientPeg } from "../MatrixClientPeg";
+import dis from "../dispatcher/dispatcher";
+import { Action } from "../dispatcher/actions";
+import { ButtonEvent } from "../components/views/elements/AccessibleButton";
+import RoomAvatar from "../components/views/avatars/RoomAvatar";
+import MemberAvatar from "../components/views/avatars/MemberAvatar";
+import { PillType } from "../components/views/elements/Pill";
+
+export interface UsePermalinkArgs {
+    room?: Room;
+    type?: PillType;
+    url?: string;
+}
+
+export interface UsePermalinkResult {
+    avatar: React.ReactElement | null;
+    text: string | null;
+    onClick: ((e: ButtonEvent) => void) | null;
+    resourceId: string | null;
+    type: PillType | "space" | null;
+}
+
+export function usePermalink({ room, type, url }: UsePermalinkArgs): UsePermalinkResult {
+    const [resourceId, setResourceId] = useState<string | null>(null);
+    const [member, setMember] = useState<RoomMember | null>(null);
+    const [resolvedRoom, setResolvedRoom] = useState<Room | null>(null);
+    const [resolvedType, setResolvedType] = useState<PillType | "space" | null>(null);
+    const [text, setText] = useState<string | null>(null);
+    const [avatar, setAvatar] = useState<React.ReactElement | null>(null);
+    const [onClick, setOnClick] = useState<((e: ButtonEvent) => void) | null>(null);
+
+    const unmountedRef = useRef(false);
+
+    useEffect(() => {
+        unmountedRef.current = false;
+        return () => {
+            unmountedRef.current = true;
+        };
+    }, []);
+
+    useEffect(() => {
+        let rid: string | null = null;
+        let ptype: PillType | "space" | null = type ?? null;
+
+        if (url) {
+            if (type) {
+                if (type === PillType.AtRoomMention) {
+                    rid = "@room";
+                } else {
+                    const parts = parsePermalink(url);
+                    rid = parts.primaryEntityId;
+                }
+            } else {
+                const parts = parsePermalink(url);
+                rid = parts.primaryEntityId;
+                const sigil = parts.sigil;
+                ptype =
+                    {
+                        "@": PillType.UserMention,
+                        "#": PillType.RoomMention,
+                        "!": PillType.RoomMention,
+                    }[sigil] ?? null;
+            }
+        }
+
+        // Resolve room for room mentions
+        let rroom: Room | null = null;
+        if (ptype === PillType.AtRoomMention) {
+            rroom = room ?? null;
+        } else if (ptype === PillType.RoomMention && rid) {
+            const client = MatrixClientPeg.get();
+            if (rid[0] === "#") {
+                rroom =
+                    client.getRooms().find((r) => r.getCanonicalAlias() === rid || r.getAltAliases().includes(rid)) ??
+                    null;
+            } else {
+                rroom = client.getRoom(rid);
+            }
+            if (rroom?.isSpaceRoom()) {
+                ptype = "space";
+            }
+        }
+
+        // Resolve member for user mentions
+        let rmember: RoomMember | null = null;
+        if (ptype === PillType.UserMention && rid) {
+            rmember = room?.getMember(rid) ?? null;
+            if (!rmember) {
+                rmember = new RoomMember(null, rid);
+                MatrixClientPeg.get()
+                    .getProfileInfo(rid)
+                    .then((resp) => {
+                        if (unmountedRef.current) return;
+                        rmember.name = resp.displayname;
+                        rmember.rawDisplayName = resp.displayname;
+                        setMember(rmember);
+                        setText(resp.displayname || rid);
+                    })
+                    .catch((err) => {
+                        logger.error("Could not retrieve profile data for " + rid + ":", err);
+                        if (!unmountedRef.current) {
+                            setText(rid);
+                        }
+                    });
+            }
+        }
+
+        setResourceId(rid);
+        setResolvedType(ptype);
+        setResolvedRoom(rroom);
+        setMember(rmember);
+
+        // Compute text
+        let t: string | null = null;
+        if (ptype === PillType.AtRoomMention) {
+            t = "@room";
+        } else if (ptype === PillType.UserMention) {
+            t = rmember?.rawDisplayName || rid;
+        } else if (ptype === PillType.RoomMention || ptype === "space") {
+            t = rroom?.name || rid;
+        }
+        setText(t);
+
+        // Compute avatar
+        let av: React.ReactElement | null = null;
+        if (ptype === PillType.AtRoomMention && rroom) {
+            av = <RoomAvatar room={rroom} width={16} height={16} aria-hidden="true" />;
+        } else if (ptype === PillType.UserMention && rmember) {
+            av = <MemberAvatar member={rmember} width={16} height={16} aria-hidden="true" hideTitle />;
+        } else if ((ptype === PillType.RoomMention || ptype === "space") && rroom) {
+            av = <RoomAvatar room={rroom} width={16} height={16} aria-hidden="true" />;
+        }
+        setAvatar(av);
+
+        // Compute onClick for user pills
+        let oc: ((e: ButtonEvent) => void) | null = null;
+        if (ptype === PillType.UserMention && rmember) {
+            oc = (e: ButtonEvent) => {
+                e.preventDefault();
+                dis.dispatch({
+                    action: Action.ViewUser,
+                    member: rmember,
+                });
+            };
+        }
+        setOnClick(oc);
+    }, [url, type, room]);
+
+    return { avatar, text, onClick, resourceId, type: resolvedType };
+}
